// PostgreSQL 新库的初始迁移，表、索引和初始数据在同一事务中创建。
export const postgresSchema = [
	`CREATE TABLE catalog_agents (
		id VARCHAR(128) PRIMARY KEY,
		slug VARCHAR(255) NOT NULL UNIQUE,
		display_name TEXT NOT NULL,
		description TEXT, icon TEXT, opening_remarks TEXT,
		suggested_prompts TEXT NOT NULL DEFAULT '[]',
		capabilities TEXT NOT NULL DEFAULT '{}',
		theme TEXT,
		remote_agent_id TEXT NOT NULL,
		remote_agent_version BIGINT,
		visibility VARCHAR(20) NOT NULL DEFAULT 'public',
		ordering BIGINT NOT NULL DEFAULT 100,
		status VARCHAR(20) NOT NULL DEFAULT 'unlisted',
		created_at VARCHAR(32) NOT NULL, updated_at VARCHAR(32) NOT NULL,
		category VARCHAR(24) NOT NULL DEFAULT 'general',
		featured SMALLINT NOT NULL DEFAULT 0,
		remote_environment_id TEXT,
		files_json TEXT NOT NULL DEFAULT '[]',
		memory_stores_json TEXT NOT NULL DEFAULT '[]',
		vault_ids_json TEXT NOT NULL DEFAULT '[]',
		agent_version BIGINT CHECK (agent_version > 0),
		listed_at VARCHAR(32)
	)`,
	`CREATE TABLE kit_audit (
		id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
		at VARCHAR(32) NOT NULL,
		subject TEXT, action TEXT NOT NULL, target TEXT, detail TEXT
	)`,
	`CREATE TABLE kit_branding (
		id INT PRIMARY KEY CHECK (id = 1),
		product_name TEXT NOT NULL, logo_url TEXT,
		updated_at VARCHAR(32) NOT NULL, updated_by TEXT
	)`,
	`CREATE TABLE kit_branding_logo (
		id INT PRIMARY KEY CHECK (id = 1),
		content_type VARCHAR(100) NOT NULL, bytes BYTEA NOT NULL,
		hash VARCHAR(128) NOT NULL, updated_at VARCHAR(32) NOT NULL
	)`,
	`CREATE TABLE kit_members (
		member_id VARCHAR(128) PRIMARY KEY,
		username VARCHAR(255) NOT NULL UNIQUE CHECK (username = lower(username)),
		display_name TEXT NOT NULL, email TEXT,
		auth_type VARCHAR(20) NOT NULL CHECK (auth_type = 'local'),
		status VARCHAR(20) NOT NULL CHECK (status = 'active'),
		password_hash TEXT NOT NULL,
		created_at VARCHAR(32) NOT NULL, updated_at VARCHAR(32) NOT NULL
	)`,
	`CREATE INDEX idx_members_created ON kit_members (created_at, member_id)`,
	`CREATE TABLE kit_groups (
		group_id VARCHAR(128) PRIMARY KEY,
		name VARCHAR(255) NOT NULL UNIQUE, description TEXT,
		revision BIGINT NOT NULL DEFAULT 1,
		created_at VARCHAR(32) NOT NULL, updated_at VARCHAR(32) NOT NULL
	)`,
	`CREATE INDEX idx_groups_created ON kit_groups (created_at, group_id)`,
	`CREATE TABLE kit_group_members (
		group_id VARCHAR(128) NOT NULL, member_id VARCHAR(128) NOT NULL,
		PRIMARY KEY (group_id, member_id),
		FOREIGN KEY (group_id) REFERENCES kit_groups(group_id),
		FOREIGN KEY (member_id) REFERENCES kit_members(member_id)
	)`,
	`CREATE INDEX idx_group_members_member ON kit_group_members (member_id, group_id)`,
	`CREATE TABLE kit_member_sessions (
		token_hash VARCHAR(128) PRIMARY KEY, member_id VARCHAR(128) NOT NULL,
		created_at VARCHAR(32) NOT NULL, expires_at VARCHAR(32) NOT NULL
	)`,
	`CREATE INDEX idx_member_sessions_expiry ON kit_member_sessions (expires_at)`,
	`CREATE INDEX idx_member_sessions_member ON kit_member_sessions (member_id)`,
	`CREATE TABLE kit_operations (
		operation_id VARCHAR(128) PRIMARY KEY,
		kind VARCHAR(100) NOT NULL, subject TEXT, status VARCHAR(20) NOT NULL, phase TEXT,
		progress DOUBLE PRECISION NOT NULL DEFAULT 0, log TEXT NOT NULL DEFAULT '[]',
		result TEXT, error TEXT,
		created_at VARCHAR(32) NOT NULL, updated_at VARCHAR(32) NOT NULL,
		publication_json TEXT, error_details_json TEXT
	)`,
	`CREATE TABLE kit_preset_packs (
		preset_pack_id VARCHAR(128) PRIMARY KEY, config_json TEXT NOT NULL, created_at VARCHAR(32) NOT NULL
	)`,
	`CREATE TABLE kit_resource_drafts (
		draft_id VARCHAR(128) PRIMARY KEY, owner VARCHAR(255) NOT NULL,
		status VARCHAR(20) NOT NULL CHECK (status IN ('draft','publishing','published','failed')),
		phase VARCHAR(20) NOT NULL CHECK (phase IN ('editable','executing','uncertain','succeeded')),
		resources_json TEXT NOT NULL DEFAULT '[]', cleanup_pending SMALLINT NOT NULL DEFAULT 0,
		operation_id VARCHAR(128), expected_revision TEXT,
		created_at VARCHAR(32) NOT NULL, updated_at VARCHAR(32) NOT NULL,
		cleanup_key_hash VARCHAR(128), engine VARCHAR(20) NOT NULL DEFAULT 'yaml',
		CHECK (cleanup_pending IN (0, 1))
	)`,
	`CREATE UNIQUE INDEX idx_resource_drafts_active_owner ON kit_resource_drafts (owner)
		WHERE status <> 'published' OR cleanup_pending = 1`,
	`CREATE TABLE kit_resource_draft_documents (
		draft_id VARCHAR(128) PRIMARY KEY, revision BIGINT NOT NULL DEFAULT 1,
		yaml TEXT NOT NULL, assets_json TEXT NOT NULL DEFAULT '[]',
		sdk_state_json TEXT NOT NULL DEFAULT '{"resources":[]}', proof_json TEXT,
		FOREIGN KEY (draft_id) REFERENCES kit_resource_drafts(draft_id) ON DELETE CASCADE
	)`,
	`CREATE TABLE kit_session_deletions (
		session_id VARCHAR(255) PRIMARY KEY, subject_id VARCHAR(512) NOT NULL,
		stage VARCHAR(20) NOT NULL, updated_at VARCHAR(32) NOT NULL
	)`,
	`CREATE TABLE kit_session_usage (
		session_id VARCHAR(255) PRIMARY KEY, member_id VARCHAR(128) NOT NULL, agent_slug VARCHAR(255) NOT NULL,
		title TEXT, status TEXT, created_at VARCHAR(32) NOT NULL,
		input_tokens BIGINT, output_tokens BIGINT, cache_read_input_tokens BIGINT, cache_creation_input_tokens BIGINT,
		active_seconds DOUBLE PRECISION, duration_seconds DOUBLE PRECISION,
		collection_status VARCHAR(20) NOT NULL DEFAULT 'pending',
		captured_at VARCHAR(32), attempted_at VARCHAR(32), capture_revision BIGINT NOT NULL DEFAULT 0,
		finalized_at VARCHAR(32), deleted_at VARCHAR(32)
	)`,
	`CREATE INDEX idx_session_usage_member ON kit_session_usage (member_id, agent_slug, created_at, session_id)`,
	`CREATE TABLE kit_sessions (
		session_id VARCHAR(255) PRIMARY KEY, subject_id VARCHAR(512) NOT NULL,
		purpose VARCHAR(20) NOT NULL DEFAULT 'experience' CHECK (purpose IN ('experience','admin_debug')),
		agent_slug VARCHAR(255), remote_agent_id TEXT, project_name VARCHAR(255), agent_key VARCHAR(255),
		project_revision TEXT, source_dirty SMALLINT, title TEXT, status TEXT,
		created_at VARCHAR(32) NOT NULL, last_event_at VARCHAR(32), files_json TEXT,
		debug_source VARCHAR(20) CHECK (debug_source IN ('project', 'template')),
		remote_environment_id TEXT, runtime_json TEXT, message_files_json TEXT,
		CHECK ((purpose = 'experience' AND agent_slug IS NOT NULL AND debug_source IS NULL)
			OR (purpose = 'admin_debug' AND agent_slug IS NULL AND remote_agent_id IS NOT NULL AND debug_source IS NOT NULL
				AND ((debug_source = 'project' AND project_name IS NOT NULL AND agent_key IS NOT NULL)
					OR (debug_source = 'template' AND project_name IS NULL AND agent_key IS NULL))))
	)`,
	`CREATE INDEX idx_sessions_subject ON kit_sessions (purpose, subject_id, created_at)`,
	`CREATE INDEX idx_debug_sessions_project ON kit_sessions (purpose, subject_id, project_name, agent_key, created_at)`,
	`CREATE TABLE kit_templates (
		template_id VARCHAR(128) PRIMARY KEY, name VARCHAR(255) NOT NULL UNIQUE,
		remote_agent_id TEXT NOT NULL, remote_agent_name TEXT NOT NULL, config_json TEXT NOT NULL,
		created_at VARCHAR(32) NOT NULL, updated_at VARCHAR(32) NOT NULL,
		version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0)
	)`,
	`CREATE INDEX idx_templates_created ON kit_templates (created_at, template_id)`,
	`CREATE TABLE kit_template_listings (
		template_id VARCHAR(128) PRIMARY KEY, catalog_id VARCHAR(128) NOT NULL UNIQUE,
		FOREIGN KEY (template_id) REFERENCES kit_templates(template_id) ON DELETE CASCADE,
		FOREIGN KEY (catalog_id) REFERENCES catalog_agents(id) ON DELETE CASCADE
	)`,
	`CREATE TABLE kit_template_versions (
		template_id VARCHAR(128) NOT NULL, version BIGINT NOT NULL CHECK (version > 0),
		config_json TEXT NOT NULL, created_at VARCHAR(32) NOT NULL,
		PRIMARY KEY (template_id, version),
		FOREIGN KEY (template_id) REFERENCES kit_templates(template_id) ON DELETE CASCADE
	)`,
	`CREATE TABLE kit_uploaded_files (
		file_id VARCHAR(255) PRIMARY KEY, subject_id VARCHAR(512) NOT NULL, created_at VARCHAR(32) NOT NULL,
		purpose VARCHAR(20) NOT NULL DEFAULT 'experience' CHECK (purpose IN ('experience','admin_debug'))
	)`,
	`CREATE INDEX idx_uploaded_files_subject ON kit_uploaded_files (subject_id)`,
	`CREATE TABLE kit_usage_limit_agent_days (
		agent_slug VARCHAR(255) NOT NULL, day VARCHAR(10) NOT NULL, tokens BIGINT NOT NULL DEFAULT 0,
		active_seconds DOUBLE PRECISION NOT NULL DEFAULT 0, PRIMARY KEY (agent_slug, day)
	)`,
	`CREATE TABLE kit_usage_limit_agent_months (
		agent_slug VARCHAR(255) NOT NULL, month VARCHAR(7) NOT NULL, tokens BIGINT NOT NULL DEFAULT 0,
		active_seconds DOUBLE PRECISION NOT NULL DEFAULT 0, tokens_unknown SMALLINT NOT NULL DEFAULT 0,
		active_seconds_unknown SMALLINT NOT NULL DEFAULT 0, PRIMARY KEY (agent_slug, month)
	)`,
	`CREATE TABLE kit_usage_limit_days (
		member_id VARCHAR(128) NOT NULL, day VARCHAR(10) NOT NULL, tokens BIGINT NOT NULL DEFAULT 0,
		active_seconds DOUBLE PRECISION NOT NULL DEFAULT 0, PRIMARY KEY (member_id, day)
	)`,
	`CREATE TABLE kit_usage_limit_members (
		member_id VARCHAR(128) PRIMARY KEY, accounting_started_at VARCHAR(32) NOT NULL
	)`,
	`CREATE TABLE kit_usage_limit_months (
		member_id VARCHAR(128) NOT NULL, month VARCHAR(7) NOT NULL, tokens BIGINT NOT NULL DEFAULT 0,
		active_seconds DOUBLE PRECISION NOT NULL DEFAULT 0, tokens_unknown SMALLINT NOT NULL DEFAULT 0,
		active_seconds_unknown SMALLINT NOT NULL DEFAULT 0, PRIMARY KEY (member_id, month)
	)`,
	`CREATE TABLE kit_usage_limit_overrides (
		member_id VARCHAR(128) PRIMARY KEY, monthly_tokens BIGINT, monthly_active_seconds DOUBLE PRECISION,
		updated_at VARCHAR(32) NOT NULL, updated_by TEXT NOT NULL, daily_tokens BIGINT, daily_active_seconds DOUBLE PRECISION
	)`,
	`CREATE TABLE kit_usage_limit_policy (
		id INT PRIMARY KEY CHECK (id = 1), monthly_tokens BIGINT, monthly_active_seconds DOUBLE PRECISION,
		updated_at VARCHAR(32), updated_by TEXT, daily_tokens BIGINT, daily_active_seconds DOUBLE PRECISION
	)`,
	`CREATE TABLE kit_usage_limit_requests (
		session_id VARCHAR(255) NOT NULL, request_key VARCHAR(255) NOT NULL, member_id VARCHAR(128) NOT NULL,
		request_hash VARCHAR(128) NOT NULL, status VARCHAR(20) NOT NULL, event_ids TEXT,
		previous_status TEXT, created_at VARCHAR(32) NOT NULL,
		PRIMARY KEY (session_id, request_key)
	)`,
	`CREATE INDEX idx_usage_limit_requests_member ON kit_usage_limit_requests (member_id, status)`,
	`CREATE TABLE kit_usage_limit_sessions (
		session_id VARCHAR(255) PRIMARY KEY, member_id VARCHAR(128) NOT NULL,
		input_tokens BIGINT, output_tokens BIGINT, active_seconds DOUBLE PRECISION,
		admission_month VARCHAR(7), captured_at VARCHAR(32)
	)`,
	`CREATE INDEX idx_usage_limit_sessions_member ON kit_usage_limit_sessions (member_id)`,
	`CREATE TABLE kit_usage_limit_templates (
		template_id VARCHAR(128) PRIMARY KEY, monthly_tokens BIGINT, monthly_active_seconds DOUBLE PRECISION,
		updated_at VARCHAR(32) NOT NULL, updated_by TEXT NOT NULL, daily_tokens BIGINT, daily_active_seconds DOUBLE PRECISION,
		FOREIGN KEY (template_id) REFERENCES kit_templates(template_id) ON DELETE CASCADE
	)`,
	`CREATE TABLE quota_override (
		subject_id VARCHAR(512) PRIMARY KEY, monthly_credits BIGINT NOT NULL, reason TEXT,
		updated_by TEXT NOT NULL, updated_at VARCHAR(32) NOT NULL
	)`,
	`CREATE TABLE quota_pack (
		id VARCHAR(128) PRIMARY KEY, subject_id VARCHAR(512) NOT NULL, month VARCHAR(7) NOT NULL, credits BIGINT NOT NULL,
		reason TEXT, granted_by TEXT NOT NULL, created_at VARCHAR(32) NOT NULL
	)`,
	`CREATE INDEX idx_quota_pack_subject ON quota_pack (subject_id, month)`,
	`CREATE TABLE quota_policy (
		id INT PRIMARY KEY CHECK (id = 1), monthly_credits BIGINT NOT NULL, updated_at VARCHAR(32), updated_by TEXT
	)`,
	`CREATE TABLE quota_request (
		id VARCHAR(128) PRIMARY KEY, subject_id VARCHAR(512) NOT NULL,
		requested_credits BIGINT NOT NULL, reason TEXT, status VARCHAR(20) NOT NULL DEFAULT 'pending',
		mode VARCHAR(20), granted_credits BIGINT, review_note TEXT, reviewed_by TEXT,
		created_at VARCHAR(32) NOT NULL, reviewed_at VARCHAR(32)
	)`,
	`CREATE INDEX idx_quota_request_subject ON quota_request (subject_id, created_at)`,
	`CREATE TABLE usage_turns (
		id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, subject_id VARCHAR(512) NOT NULL, agent_slug VARCHAR(255) NOT NULL,
		session_id VARCHAR(255) NOT NULL, client_message_id VARCHAR(255), day VARCHAR(10) NOT NULL,
		month VARCHAR(7) NOT NULL, created_at VARCHAR(32) NOT NULL
	)`,
	`CREATE UNIQUE INDEX idx_usage_turns_idempotency ON usage_turns (session_id, client_message_id)`,
	`CREATE INDEX idx_usage_turns_month_agent ON usage_turns (month, agent_slug)`,
	`CREATE INDEX idx_usage_turns_subject_month ON usage_turns (subject_id, month)`,
];
